  Widget driverStatistics(){final list=s.jobs.where((j)=>text(j,j['completed']!=null?'completed':j['cancelAt']!=null?'cancelAt':'created').startsWith(month)).toList();final done=list.where((j)=>j['status']=='작업 완료').toList();final byType=<String,int>{};for(final j in done){byType[text(j,'type')]=(byType[text(j,'type')]??0)+1;}void shift(int delta){final d=DateTime.parse('$month-01');final next=DateTime(d.year,d.month+delta);refresh(()=>month='${next.year}-${next.month.toString().padLeft(2,'0')}');}return stack([Row(children:[IconButton(onPressed:()=>shift(-1),icon:const Icon(Icons.chevron_left)),Expanded(child:Center(child:heading(month))),IconButton(onPressed:()=>shift(1),icon:const Icon(Icons.chevron_right))]),box([heading('월별 작업 현황'),Wrap(spacing:24,children:[kv('배정','${list.where((j)=>j['assigned']==true||j['cancelAt']!=null).length}건'),kv('완료','${done.length}건'),kv('취소','${list.where((j)=>j['status']=='배차 취소').length}건')])]),box([heading('전문 분야별 완료 건수'),for(final item in byType.entries)kv(item.key,'${item.value}건 · ${done.isEmpty?0:(item.value/done.length*100).round()}%')]),heading('작업 내역'),for(final j in list)jobCard(j),if(list.isEmpty)empty('해당 월의 작업 내역이 없습니다.')]);}
